head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.v_SaveKind = ""; // 신규,수정 구분
scwin.vBzProcsNo = ""; // 업무처리번호
scwin.vAcptNo = ""; // 접수번호
scwin.vIsurCd = ""; // 발행기관코드
scwin.vIsurNm = ""; // 발행회사명
scwin.vIsuAbbrv = ""; // 종목약명
scwin.vNapplShrs = ""; // 미반영증권수
scwin.vChgAfListShrs = ""; // 변경후증권수
scwin.vListBzTpCd = ""; // 상장업무구분코드 (삭제시 필요) - 로그처리방지용
// 화면ID

// Transaction 처리코드
scwin.TR_JOB;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name checkForm
 * @description Form Validation Check
 * @param {*} kind kind
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function(kind) {
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (txb_INCDEC_APPL_LIST_SHRS.getValue() === "") {
        txb_INCDEC_APPL_LIST_SHRS.setValue("0");
    }
    if (edt_HALFWY_REDMPT_DD.getValue() === "") {
        await $c.win.alert("[중도상환일]을 입력하세요.");
        edt_HALFWY_REDMPT_DD.focus();
        return false;
    } else if (edt_CHG_LIST_DD.getValue() === "") {
        await $c.win.alert("[변경상장일]을 입력하세요.");
        edt_CHG_LIST_DD.focus();
        return false;
    }

    // 신규인 경우에만 체크하도록 함
    if (scwin.v_SaveKind === "N") {
        if (vCurDate >= edt_CHG_LIST_DD.getValue()) {
            await $c.win.alert("[변경상장일]을 현재일이후로 입력하세요.");
            edt_CHG_LIST_DD.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name selectIsurInit
 * @description 종목코드에 대한 발행회사 조회 / 신규시 초기화됨
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectIsurInit = async function() {
    let parentWin = $c.frame.path("../");
    url += "&SCREN_ID=" + "ULDSTF08023.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&SRCH_ISU_CD=" + txb_ISU_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/etn/EtnChgList.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 발행기관명, 미반영증권수,  변경후증권수 조회
    vIsuNm = dts_Isu.getCellData(1, "ISU_NM");
    scwin.vIsurNm = dts_Isu.getCellData(1, "ISUR_NM");
    scwin.vNapplShrs = dts_Isu.getCellData(1, "NAPPL_SHRS");
    scwin.vChgAfListShrs = dts_Isu.getCellData(1, "CHG_AF_LIST_SHRS");
};

/**
 * @method
 * @name selectIsurDetail
 * @description 업무처리번호에 대한 상세내역 조회
 * @param {*} selectKind selectKind
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectIsurDetail = async function(selectKind) {
    let parentWin = $c.frame.path("../");
    url += "&SCREN_ID=" + "ULDSTF08023.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    url += "&LIST_BZ_TP_CD=" + selectKind;
    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/etn/EtnChgList.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 발행기관명, 종목약명 획득 (안내문전송에서 사용함)
    vIsuNm = dts_Isu.getCellData(1, "ISU_NM");
    scwin.vIsuAbbrv = dts_Isu.getCellData(1, "ISU_ABBRV");
    scwin.vIsurNm = dts_Isu.getCellData(1, "ISUR_NM");
    scwin.vAcptNo = dts_Isu.getCellData(1, "ACPT_NO");
};

/**
 * @method
 * @name saveQtyIsurNew
 * @description 수량변경 > 발행 및 상장내역 > 신규저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveQtyIsurNew = async function() {
    if ($c.en.fn_CheckForm(scwin.v_SaveKind) === false) return;
    scwin.TR_JOB = 'I';

    // Transaction 처리전 안내문구
    if ($c.ut.trim(txb_INCDEC_APPL_LIST_SHRS.getValue()) === "") {
        txb_INCDEC_APPL_LIST_SHRS.setValue("0");
    }
    const rstlMsg = true;
    if (parseInt(txb_INCDEC_APPL_LIST_SHRS.getValue()) > 0) {
        LastJob = '저장'; // list_common_etn.js에 있는 상장메세지처리관련
        // var rstlMsg = confirm("[증감증권수]는 0 이하의 수만 입력가능합니다.\n\n현재 상태로 [저장] 처리하시겠습니까?");
        // if (rstlMsg == false) {
        //    return;
        // }
        await $c.win.alert("[증감증권수]는 0 이하의 수만 입력가능합니다.");
        return;
    } else {
        if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
    }

    // 저장 처리
    let vScrenId = "SCREN_ID=" + "ULDSTF08023.xml";
    let vScrenTpId = "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    let vSrvMethod = "&method=insertQtyIsurDtl";
    scwin.vIsurCd = dts_Isu.getCellData(1, "ISUR_CD"); // 발행기관 (조회해 온 데이터)
    scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo); // 업무처리번호 새로 지정

    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : TR_JOB_INSERT,
    //     LIST_BZ_TP_CD : LIST_BZ_TP_CD_708,
    //     BZ_PROCS_NO : scwin.vBzProcsNo,
    //     ISUR_CD : scwin.vIsurCd,
    //     LD_MKT_TP_CD : "1",
    //     TRANSTR_EMP_NO : js_emp_no
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/etn/EtnChgList.do",
        ref : "dts_Isu",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name saveQtyIsurUpdate
 * @description 수량변경 > 발행 및 상장내역 > 수정
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveQtyIsurUpdate = async function() {
    // 중도상환인 경우에만 폼 데이터 체크함
    if (scwin.vListBzTpCd === "708") {
        if ($c.en.fn_CheckForm(scwin.v_SaveKind) === false) return;
    }
    scwin.TR_JOB = 'U';

    // Transaction 처리전 안내문구
    if ($c.ut.trim(txb_INCDEC_APPL_LIST_SHRS.getValue()) === "") {
        txb_INCDEC_APPL_LIST_SHRS.setValue("0");
    }
    /**
     * 중도상환인 경우만 증감증권수 validation check
     */
    let m_ListBzTpCd = "";
    if (scwin.vListBzTpCd === "708") {
        // 상장업무구분 (중도상환)
        m_ListBzTpCd = LIST_BZ_TP_CD_708;

        // 증감증권수 체크
        if (parseInt(txb_INCDEC_APPL_LIST_SHRS.getValue()) > 0) {
            LastJob = '수정'; // list_common_etn.js에 있는 상장메세지처리관련
            await $c.win.alert("[증감증권수]는 0 이하의 수만 입력가능합니다.");
            return;
        } else {
            if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
        }
    } else if (scwin.vListBzTpCd === "704") {
        // 상장업무구분 (추가상장)
        m_ListBzTpCd = LIST_BZ_TP_CD_704;

        // 증감증권수 체크
        if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
    }
    let vScrenId = "SCREN_ID=" + "ULDSTF08023.xml";
    let vScrenTpId = "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    let vSrvMethod = "&method=updateQtyIsurDtl";
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : TR_JOB_UPDATE,
    //     LIST_BZ_TP_CD : m_ListBzTpCd,
    //     BZ_PROCS_NO : scwin.vBzProcsNo,
    //     LD_MKT_TP_CD : "1",
    //     TRANSTR_EMP_NO : js_emp_no
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/etn/EtnChgList.do",
        ref : "dts_Isu",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name saveQtyIsurDelete
 * @description 수량변경 > 발행 및 상장내역 > 삭제
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveQtyIsurDelete = async function() {
    if (scwin.vBzProcsNo === "") {
        await $c.win.alert("삭제 정보(업무처리번호)가 없습니다.");
        return;
    }
    scwin.TR_JOB = 'D';

    // Transaction 처리전 안내문구
    if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
    let vScrenId = "SCREN_ID=" + "ULDSTF08023.xml";
    let vScrenTpId = "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    let vSrvMethod = "&method=deleteQtyIsurDtl";
    let m_ListBzTpCd = "";
    if (scwin.vListBzTpCd === "704") {
        m_ListBzTpCd = LIST_BZ_TP_CD_704;
    } else if (scwin.vListBzTpCd === "708") {
        m_ListBzTpCd = LIST_BZ_TP_CD_708;
    }

    // 상장업무구분코드 있는 경우에만 삭제 처리 함
    if (m_ListBzTpCd !== "") {
        trs_Save.KeyName = "toinb_dataid4";
        // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     TRS_IDX : TR_JOB_DELETE,
        //     LIST_BZ_TP_CD : m_ListBzTpCd,
        //     BZ_PROCS_NO : scwin.vBzProcsNo,
        //     ACPT_NO : scwin.vAcptNo,
        //     LD_MKT_TP_CD : "1",
        //     TRANSTR_EMP_NO : js_emp_no
        // };
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/etn/EtnChgList.do",
            ref : "dts_Isu",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**********************************************
 * 함수명 : fn_dscl()
 * 설명    : 수량변경 > 발행 및 상장내역 > 안내문 작성
 ***********************************************/
scwin.getPar, scwin.setPar;

/**
 * @method
 * @name dscl
 * @description dscl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
    const cCtnt = "";
    scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2) {
        arr[0] = "68353";
        arr[1] = scwin.vBzProcsNo;
        arr[2] = scwin.vIsurCd;
        arr[3] = '1';
        arr[4] = scwin.getQtyChgDisclsCtnt(); // ctnt
        arr[5] = scwin.vIsuAbbrv; // add  title

        $c.stf.copyDataSet(dts_Isu, param_dts_isu);

        // param_dts_mst.NameString(param_dts_mst.RowPosition, "TGT_NM") = Isur_nm ;

        return arr.length;
    };
    scwin.setPar = function(arr) {

    };
    const wth = 750;
    const hgt = 820;
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "변경상장 수량변경 안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;

    // 안내문팝업 후 '닫기'나 '안내문전송' 후에 Popup Close 및 Parent Refresh 함
    $c.frame.path("../").fn_list_sync();
};

/**
 * @method
 * @name getQtyChgDisclsCtnt
 * @description 안내문작성 서식 (수량변경)
 * @returns {void}
 * @hidden N
 */
scwin.getQtyChgDisclsCtnt = function() {
    let vCtnt = "";
    let indecShrs = 0;
    let chgPreShrs = 0;
    let chgAfshrs = 0;
    let lpHdQty = 0;

    // Comma 처리
    indecShrs = (parseInt(txb_INCDEC_APPL_LIST_SHRS.getValue()) < 0) ? $c.stf.addCommaMinus(txb_INCDEC_APPL_LIST_SHRS.getValue()) : $c.stf.addComma(txb_INCDEC_APPL_LIST_SHRS.getValue());
    chgPreShrs = (parseInt(txb_CHG_PRE_LIST_SHRS.getValue()) < 0) ? $c.stf.addCommaMinus(txb_CHG_PRE_LIST_SHRS.getValue()) : $c.stf.addComma(txb_CHG_PRE_LIST_SHRS.getValue());
    chgAfshrs = (parseInt(txb_CHG_AF_LIST_SHRS.getValue()) < 0) ? $c.stf.addCommaMinus(txb_CHG_AF_LIST_SHRS.getValue()) : $c.stf.addComma(txb_CHG_AF_LIST_SHRS.getValue());
    lpHdQty = (parseInt(txb_LP_HD_QTY.getValue()) < 0) ? $c.stf.addCommaMinus(txb_LP_HD_QTY.getValue()) : $c.stf.addComma(txb_LP_HD_QTY.getValue());
    vCtnt += "[공시제목] 상장지수증권 변경상장(수량감소)";
    vCtnt += "\r\n\r\n";
    vCtnt += "[본문내용]";
    vCtnt += "\r\n\r\n";
    vCtnt += "◎ " + scwin.vIsurNm + " 발행 상장지수증권 변경상장(수량감소)";
    vCtnt += "\r\n\r\n";
    vCtnt += "1. 종목명 : " + vIsuNm; // getObjectValue(txb_ISU_NM);
    vCtnt += "\r\n\r\n";
    vCtnt += "2. 감소수량 : " + indecShrs;
    vCtnt += "\r\n\r\n";
    vCtnt += "3. 상장증권수 : 변경상장전 " + chgPreShrs + " → 변경상장후 " + chgAfshrs;
    vCtnt += "\r\n\r\n";
    vCtnt += "4. 감소되는 수량 중 LP 보유수량 : " + lpHdQty;
    vCtnt += "\r\n\r\n";
    vCtnt += "5. 변경상장일 : " + scwin.dateForm(edt_CHG_LIST_DD.getValue());
    vCtnt += "\r\n\r\n";
    return vCtnt;
};

/**
 * @method
 * @name dateForm
 * @description 년월일 포맷 맞춤 (안내문 작성에서 사용)
 * @param {String} pStr pStr
 * @returns {void}
 * @hidden N
 */
scwin.dateForm = function(pStr) {
    let str = "";
    if (pStr === "") {
        str = "★★★★년" + "★★월" + "★★일";
    } else {
        str = pStr.substring(0, 4) + "년 " + pStr.substring(4, 6) + "월 " + pStr.substring(6, 8) + "일";
    }
    return str;
};

/**
 * @method
 * @name parentRefresh
 * @description Parent 화면 Refresh()
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function() {
    // Parent 신청내역 화면 Refresh
    let parentWin = $c.frame.path("../");
    parentWin.fn_list_sync();
};

/**********************************************
 * 함수명 : fn_parentRefresh2()
 * 설명    : Parent 화면 Refresh()
 ***********************************************/

/**
 * @method
 * @name btn_QtyIsuClose_onclick
 * @description //Parent 신청내역 화면 Refresh
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_QtyIsuClose_onclick = async function() {
    // 닫기(수량변경)
    await $c.win.closePopup();
};

/**
 * @method
 * @name gform_onload
 * @description Form onload event
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    // Form onload event
    $c.libRoundPanel.PanelToGroupBox(panel_Item);
    let parentWin = $c.frame.path("../");

    // Transaction 구분: 신규(N), 수정(U), 삭제(D)
    scwin.v_SaveKind = parentWin.vQtyIsurKind;
    if (scwin.v_SaveKind === "N") {
        // 신규일 경우
        // 수정,삭제,안내문작성 버튼 비활성화
        btn_QtyIsuUpdate.setBackgroundImage("../img/btn_modify_d.gif");
        btn_QtyIsuUpdate.setDisabled(true);
        btn_QtyIsuDel.setBackgroundImage("../img/btn_RcvdocDel_d.gif");
        btn_QtyIsuDel.setDisabled(true);
        btn_QtyIsuDscl.setBackgroundImage("../img/btn_make_info_d.gif");
        btn_QtyIsuDscl.setDisabled(true);
        txb_ISU_CD.setValue(parentWin.txb_SearchIsuCd.getValue());

        // 종목코드 Textbox 설정 및 종목코드 정보 조회
        await scwin.selectIsurInit();
    } else if (scwin.v_SaveKind === "U") {
        // 수정일 경우
        const v_UpdParam = parentWin.v_UpdQtyIsurParam;
        let vDisclsYn;
        let i = 0;
        scwin.vBzProcsNo = v_UpdParam[i++]; // 업무처리번호
        scwin.vIsurCd = v_UpdParam[i++]; // 발행기관코드
        vDisclsYn = v_UpdParam[i++]; // 공시여부
        scwin.vListBzTpCd = v_UpdParam[i++]; // 상장업무구분코드

        // 세부내역 조회
        await scwin.selectIsurDetail(scwin.vListBzTpCd);
        btn_QtyIsuSave.setBackgroundImage("../img/btn_save_d.gif");
        btn_QtyIsuSave.setDisabled(true);

        // 공시여부('Y')인 경우 화면의 모든 버튼 상태를 disabled 로 변경
        if (vDisclsYn === 'Y') {
            // 상장업무구분코드(신규상장:702)
            if (scwin.vListBzTpCd === "702") {
                txb_ApplType.setValue("신규상장");
                txb_RedMpt_Dd.setValue("발행일");
                txb_ListDd.setValue("신규상장일");
                txb_NAPPL_SHRS.setReadOnly(true);
                btn_QtyIsuDel.setBackgroundImage("../img/btn_RcvdocDel_d.gif");
                btn_QtyIsuDel.setDisabled(true);
                btn_QtyIsuUpdate.setBackgroundImage("../img/btn_modify_d.gif");
                btn_QtyIsuUpdate.setDisabled(true);

                // 상장업무구분코드(추가상장:704)

            } else if (scwin.vListBzTpCd === "704") {
                txb_ApplType.setValue("추가상장");
                txb_RedMpt_Dd.setValue("추가발행일");
                txb_ListDd.setValue("추가상장일");
            }

            // 상장업무구분코드(신규상장:702, 추가상장:704)
            if (scwin.vListBzTpCd === "702" || scwin.vListBzTpCd === "704") {
                f_FormAllControlDisabled();
            }
        }

        // 추가상장, 중도상환인 경우
        // 상장일이 지난 경우(오늘 포함)는 컨트롤 비활성화 및 readonly
        //  대상:  '삭제'버튼,  '증감' 필드 readonly, 변경상장일, 중도상환일
        if (scwin.vListBzTpCd === "704" || scwin.vListBzTpCd === "708") {
            // 상장일 체크
            if (edt_CHG_LIST_DD.getValue() <= $c.ut.cGetToday("yyyymmdd")) {
                f_FormAllControlDisabled();
            } else {
                // 변경전 증권수 활성화
                txb_CHG_PRE_LIST_SHRS.setReadOnly(false);

                // 삭제버튼 활성화
                btn_QtyIsuDel.setBackgroundImage("../img/btn_RcvdocDel.gif");
                btn_QtyIsuDel.setDisabled(false);
            }
        }
    }

    // 컨트롤 비활성화
    function f_FormAllControlDisabled() {
        // 버튼:삭제,안내문전송
        btn_QtyIsuDel.setBackgroundImage("../img/btn_RcvdocDel_d.gif");
        btn_QtyIsuDel.setDisabled(true);
        btn_QtyIsuDscl.setBackgroundImage("../img/btn_make_info_d.gif");
        btn_QtyIsuDscl.setDisabled(true);

        // 텍스트:증감증권수,LP보유량
        txb_INCDEC_APPL_LIST_SHRS.setReadOnly(true);
        txb_LP_HD_QTY.setReadOnly(true);

        // 달력:발행일,신규상장일
        edt_HALFWY_REDMPT_DD.setReadOnly(true);
        img_HALFWY_REDMPT_DD.setDisabled(true);
        img_HALFWY_REDMPT_DD.src = "../img/icn_calendar_d.gif";
        edt_CHG_LIST_DD.setReadOnly(true);
        img_CHG_LIST_DD.setDisabled(true);
        img_CHG_LIST_DD.src = "../img/icn_calendar_d.gif";
    };
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description 저장메세지, 부모화면 Refresh, 화면 닫기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    // 저장메세지, 부모화면 Refresh, 화면 닫기
    $c.lce.fn_alertMsg('S');
    scwin.parentRefresh();
    await $c.win.closePopup();
};

/**
