/**
 * @method
 * @name txb_INCDEC_APPL_LIST_SHRS_onkeyup
 * @description 수량변경 > 발행 및 상장내역  > 세부 > 증감증권수 onkeyup
 * @param {*} keycode keycode
 * @param {*} skeycode skeycode
 * @returns {void}
 * @hidden N
 */
scwin.txb_INCDEC_APPL_LIST_SHRS_onkeyup = function(keycode, skeycode) {
    // 수량변경 > 발행 및 상장내역  > 세부 > 증감증권수 onkeyup
    if ($c.ut.trim(txb_INCDEC_APPL_LIST_SHRS.getValue()) === "-0") {
        txb_INCDEC_APPL_LIST_SHRS.setValue("0");
    }
    let rsltCalc = 0;
    if ($c.ut.trim(txb_INCDEC_APPL_LIST_SHRS.getValue()) === "" || $c.ut.trim(txb_INCDEC_APPL_LIST_SHRS.getValue()) === "-") {
        rsltCalc = parseInt(txb_CHG_PRE_LIST_SHRS.getValue()) + parseInt(txb_NAPPL_SHRS.getValue());
    } else {
        rsltCalc = parseInt(txb_CHG_PRE_LIST_SHRS.getValue()) + parseInt(txb_INCDEC_APPL_LIST_SHRS.getValue()) + parseInt(txb_NAPPL_SHRS.getValue());
    }
    txb_CHG_AF_LIST_SHRS.setValue(rsltCalc);
};

